program='''def transform(grid):
    h, w = len(grid), len(grid[0])
    original = [row[:] for row in grid]
    centers = []
    blank_columns = set()
    for r in range(1, h - 1):
        for c in range(1, w - 1):
            if (grid[r - 1][c] == 3 and grid[r + 1][c] == 3 and
                    grid[r][c - 1] == 3 and grid[r][c + 1] == 3):
                if grid[r][c] == 0:
                    blank_columns.add(c)
                elif grid[r][c] != 3:
                    centers.append((r, c, grid[r][c]))

    out = [[0] * w for _ in range(h)]
    for r, c, color in centers:
        out[r][c] = color
        for dr, dc, horizontal in ((0, -1, True), (0, 1, True), (-1, 0, False), (1, 0, False)):
            y, x = r + dr, c + dc
            distance = 1
            while 0 <= y < h and 0 <= x < w:
                if original[y][x] == 3:
                    if distance > 1:
                        break
                    out[y][x] = 3
                elif horizontal and x in blank_columns:
                    pass
                else:
                    out[y][x] = color
                y += dr
                x += dc
                distance += 1
    # Vertical rays take precedence over horizontal rays at crossings.
    # Redraw them after all horizontal rays, with the same spoke barriers.
    for r, c, color in centers:
        for dr in (-1, 1):
            y = r + dr
            distance = 1
            while 0 <= y < h:
                if original[y][c] == 3:
                    if distance > 1:
                        break
                    out[y][c] = 3
                else:
                    out[y][c] = color
                y += dr
                distance += 1
    for r in range(h):
        for c in range(w):
            if original[r][c] == 3:
                out[r][c] = 3
    return out
'''
